<script>
(() => {
 const root=document.querySelector('.pc-workspace');if(!root)return;
 let toast=root.querySelector('[data-product-toast]');if(!toast){toast=document.createElement('div');toast.className='pc-toast';toast.hidden=true;toast.setAttribute('role','alert');root.append(toast)}let timer;
 const notify=message=>{toast.textContent=message;toast.hidden=false;clearTimeout(timer);timer=setTimeout(()=>toast.hidden=true,6500)};
 const serverError=root.querySelector('.pc-error');if(serverError)notify(serverError.innerText.trim());
 root.querySelectorAll('[data-option-picker]').forEach(picker=>{const search=picker.querySelector('[data-option-search]'),count=picker.querySelector('[data-option-count]');picker.addEventListener('change',()=>{count.textContent=picker.querySelectorAll('input[type=checkbox]:checked').length});search?.addEventListener('input',()=>{const query=search.value.trim().toLocaleLowerCase();let visible=0;picker.querySelectorAll('[data-option-group]').forEach(group=>{group.hidden=!group.dataset.optionName.includes(query);if(!group.hidden)visible++});picker.querySelector('[data-no-options]').hidden=visible>0})});
 const productForm=root.querySelector('[data-product-form]');
 if(productForm){
  const name=productForm.querySelector('[data-product-name]'),price=productForm.querySelector('[data-product-price]'),offer=productForm.querySelector('[data-product-offer]');
  const update=()=>{root.querySelector('[data-preview-name]').textContent=name.value.trim()||'Your product name';const amount=offer.value!==''?Number(offer.value):Number(price.value);root.querySelector('[data-preview-price]').textContent=new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR'}).format(Number.isFinite(amount)?amount:0);offer.max=price.value||''};productForm.addEventListener('input',update);update();
  const image=productForm.querySelector('[data-image-input]');let objectUrl;
  image?.addEventListener('change',()=>{const file=image.files[0];if(!file)return;if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>3*1024*1024){notify('Choose a JPG, PNG or WebP image up to 3 MB.');image.value='';return}if(objectUrl)URL.revokeObjectURL(objectUrl);objectUrl=URL.createObjectURL(file);const preview=document.createElement('img');preview.src=objectUrl;preview.alt='Selected product image';root.querySelector('[data-image-preview]').replaceChildren(preview)});
  const rows=productForm.querySelector('[data-spec-rows]');let next=Math.max(-1,...[...rows.querySelectorAll('input')].map(i=>Number(i.name.match(/\[(\d+)\]/)?.[1]??-1)))+1;
  productForm.querySelector('[data-add-spec]').addEventListener('click',()=>{if(rows.querySelectorAll('[data-spec-row]').length>=30){notify('You can add up to 30 specifications.');return}const row=document.createElement('div');row.className='pc-spec-row';row.dataset.specRow='';const index=next++;[['name','Detail name','Warranty',255],['value','Detail value','1 year',1000]].forEach(([key,title,placeholder,maxLength])=>{const label=document.createElement('label');label.className='pc-field';label.textContent=title;const input=document.createElement('input');input.name=`specifications[${index}][${key}]`;input.maxLength=maxLength;input.placeholder=placeholder;label.append(input);row.append(label)});const button=document.createElement('button');button.type='button';button.className='pc-button pc-secondary';button.dataset.removeSpec='';button.textContent='Remove';row.append(button);rows.append(row)});
  rows.addEventListener('click',event=>event.target.closest('[data-remove-spec]')?.closest('[data-spec-row]')?.remove());
  productForm.addEventListener('submit',event=>{let invalid=false;rows.querySelectorAll('[data-spec-row]').forEach(row=>{const inputs=row.querySelectorAll('input');if(Boolean(inputs[0].value.trim())!==Boolean(inputs[1].value.trim()))invalid=true});if(invalid){event.preventDefault();notify('Each specification needs both a name and a value.');rows.closest('details').open=true}});
 }
 root.querySelectorAll('[data-variant-form]').forEach(form=>{const name=form.querySelector('[data-variant-name]'),price=form.querySelector('[data-variant-price]'),offer=form.querySelector('[data-variant-offer]');let manual=Boolean(name.value);name.addEventListener('input',()=>manual=Boolean(name.value));const update=()=>{const values=[...form.querySelectorAll('[data-variant-option]')].filter(s=>s.value).map(s=>s.selectedOptions[0].textContent);const suggestion=values.join(' / ');const preview=form.querySelector('[data-combination-preview]');if(preview)preview.textContent=suggestion||'Named variant — no values selected';if(!manual)name.value=suggestion;offer.max=price.value||''};form.addEventListener('change',update);price.addEventListener('input',update);update()});
 root.querySelectorAll('[data-confirm-delete]').forEach(form=>form.addEventListener('submit',event=>{if(!confirm('Delete this variant? Variants used in carts or orders will be kept.'))event.preventDefault()}));
 // Reveal invalid fields even when they are inside an optional collapsed section.
 root.addEventListener('invalid',event=>{let parent=event.target.closest('details');while(parent){parent.open=true;parent=parent.parentElement?.closest('details')}},true);
})();
</script>
